describe('Search Filter - No Results Message', () => {
  beforeEach(() => {
    cy.visit('/search');
  });

  it('should display "No results found" when no items match search query', () => {
    // Setup: Intercept the search API call
    cy.intercept('GET', '/api/search*', (req) => {
      req.reply((res) => {
        res.body = {
          results: [],
          total: 0,
          has_more: false,
          next_page_token: null
        };
      });
    }).as('searchResults');

    // Perform search with no results
    cy.get('[data-testid="search-input"]').type('nonexistent product');
    cy.get('[data-testid="search-button"]').click();

    // Wait for API response
    cy.wait('@searchResults');

    // Verify "No results found" message is displayed
    cy.get('[data-testid="no-results-message"]')
      .should('be.visible')
      .should('contain', 'No results found');

    // Verify search results container is empty
    cy.get('[data-testid="search-results-container"]')
      .should('be.visible')
      .should('have.length', 0);

    // Verify no pagination links are shown
    cy.get('[data-testid="next-page-link"]')
      .should('not.exist');

    // Verify search input is cleared
    cy.get('[data-testid="search-input"]').should('have.value', '');
  });

  it('should handle empty search input gracefully', () => {
    // Setup: Intercept the search API call
    cy.intercept('GET', '/api/search*', (req) => {
      req.reply((res) => {
        res.body = {
          results: [],
          total: 0,
          has_more: false,
          next_page_token: null
        };
      });
    }).as('searchResults');

    // Verify "No results found" message is not displayed when search input is empty
    cy.get('[data-testid="search-input"]').should('be.visible');
    cy.get('[data-testid="search-input"]').clear();

    cy.get('[data-testid="search-button"]').click();

    // Wait for API response
    cy.wait('@searchResults');

    // Verify "No results found" message is not visible
    cy.get('[data-testid="no-results-message"]')
      .should('not.exist');

    // Verify search results container is still empty
    cy.get('[data-testid="search-results-container"]')
      .should('be.visible')
      .should('have.length', 0);

    // Verify search input is cleared
    cy.get('[data-testid="search-input"]').should('have.value', '');
  });
});
